from pathlib import Path
p=Path('.env.example')
s=p.read_text(encoding='utf-8').replace('PORT=4000','PORT=5000').replace('CASE_TTL_DAYS=30','CASE_TTL_DAYS=30\nGENERATION_MAX_ATTEMPTS=3\nGENERATION_TIMEOUT_MS=90000')
p.write_text(s,encoding='utf-8')
Path('server/.env.example').write_text(s,encoding='utf-8')
Path('server/.env').write_text(s.replace('GEMINI_API_KEY=','GEMINI_API_KEY=replace_with_your_key'),encoding='utf-8')
client_env='VITE_API_BASE_URL=/api/v1\n'
Path('client/.env.example').write_text(client_env,encoding='utf-8')
Path('client/.env').write_text(client_env,encoding='utf-8')
p=Path('client/vite.config.js'); s=p.read_text(encoding='utf-8').replace("'http://localhost:4000'","'http://localhost:5000'"); p.write_text(s,encoding='utf-8')
p=Path('server/src/index.js'); s=p.read_text(encoding='utf-8')
s=s.replace("import 'dotenv/config';", "import 'dotenv/config';\nimport { randomUUID } from 'node:crypto';")
s=s.replace("Number(process.env.PORT)||4000", "Number(process.env.PORT)||5000")
p.write_text(s,encoding='utf-8')
p=Path('client/src/lib/api.js'); s=p.read_text(encoding='utf-8').replace('`/api/v1${path}`', '`${import.meta.env.VITE_API_BASE_URL || \'/api/v1\'}${path}`'); p.write_text(s,encoding='utf-8')
p=Path('server/src/services/gemini.js'); s=p.read_text(encoding='utf-8')
s=s.replace('for(let attempt=0;attempt<2;attempt++){', "const maxAttempts=Math.max(1,Math.min(5,Number(process.env.GENERATION_MAX_ATTEMPTS)||3));\n const timeoutMs=Math.max(10000,Math.min(180000,Number(process.env.GENERATION_TIMEOUT_MS)||90000));\n for(let attempt=0;attempt<maxAttempts;attempt++){")
s=s.replace(')),45000);', ')),timeoutMs);')
p.write_text(s,encoding='utf-8')
p=Path('README.md'); s=p.read_text(encoding='utf-8')
s=s.replace('1. Copy `.env.example` to `.env` in the project root.\n2. Set `MONGODB_URI`, `GEMINI_API_KEY`.\n3. Install the workspace and service dependencies:', '1. Copy `server/.env.example` to `server/.env` and `client/.env.example` to `client/.env`.\n2. Set `MONGODB_URI` and your real `GEMINI_API_KEY` in `server/.env`. The checked-in example uses a placeholder only.\n3. Install the workspace and service dependencies:')
s=s.replace('port 4000.', 'port 5000.').replace('bounded repair attempt', 'bounded generation attempts and timeout').replace('If Gemini is not configured, case creation returns a clear service error; it never substitutes a fake generated case.', 'If Gemini is not configured, case creation returns a clear service error; it never substitutes a fake generated case. `GENERATION_MAX_ATTEMPTS` and `GENERATION_TIMEOUT_MS` control generation retries and the request timeout.')
p.write_text(s,encoding='utf-8')
Path('client/public/media').mkdir(parents=True,exist_ok=True)
Path('client/public/media/.gitkeep').write_text('',encoding='utf-8')
